// Product rows with today's rank next to the previous run's rank (workflow static data), sorted by rank.
const MAX_KEYS = 5000;                       // category|chart|asin keys remembered (oldest dropped)
const store = $getWorkflowStaticData('global');
store.ranks = store.ranks || {};
const known = new Set(Object.keys(store.ranks).map(k => k.split('|').slice(0, 2).join('|')));   // lists seen before
const today = new Date().toISOString().slice(0, 10);
const rows = $input.all().map(i => i.json).filter(r => r.type === 'product' && r.asin);
const out = rows.map(r => {
  const list = r.category || r.query || '';          // chart category, or the keyword when tracking search results
  const kind = r.chart || 'search';
  const rank = r.rank ?? r.position;                  // rank on a chart, position on a search page
  const key = `${list}|${kind}|${r.asin}`;
  const first_run = !known.has(`${list}|${kind}`);    // first time this list is seen: every product is "new", so no alerts
  const prev = store.ranks[key];
  const change = prev == null ? 'new' : prev === rank ? '0' : `${prev - rank > 0 ? '+' : ''}${prev - rank}`;
  store.ranks[key] = rank;
  return { json: { date: today, category: list, chart: kind, rank, previous_rank: prev ?? null, change, asin: r.asin, title: r.title || '',
    price: r.price ?? null, price_display: r.price_display || '', rating: r.rating ?? null, ratings_count: r.ratings_count ?? null, url: r.url || '', first_run } };
}).sort((a, b) => (a.json.rank ?? 1e9) - (b.json.rank ?? 1e9));
const keys = Object.keys(store.ranks);
if (keys.length > MAX_KEYS) for (const k of keys.slice(0, keys.length - MAX_KEYS)) delete store.ranks[k];
return out;
